<script lang="ts">
 import {onMount} from 'svelte';import {locale,t} from '$lib/i18n';
 let data=$state<any>(null),message=$state(''),busy=$state(false),supported=$state(false),enabled=$state(false);
 const names:Record<string,string>={request_created:'New requests',request_approved:'Request approved',request_rejected:'Request declined',request_finished:'Available in Emby'};
 async function load(){try{const r=await fetch('/api/v1/account-notifications/preferences');if(!r.ok)throw Error('Notification settings could not be loaded.');data=await r.json();supported=window.isSecureContext&&'serviceWorker' in navigator&&'PushManager' in window;if(supported){const reg=await navigator.serviceWorker.getRegistration('/web/');enabled=!!(await reg?.pushManager.getSubscription());}}catch(e){message=(e as Error).message;}}
 async function save(){busy=true;try{const r=await fetch('/api/v1/account-notifications/preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({categories:data.categories})});if(!r.ok)throw Error('Notification settings could not be saved.');message='Notification settings saved.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function push(){busy=true;try{if(enabled){const reg=await navigator.serviceWorker.getRegistration('/web/');const sub=await reg?.pushManager.getSubscription();if(sub){const r=await fetch('/api/v1/account-notifications/push',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});if(!r.ok)throw Error('Push registration failed.');await sub.unsubscribe();}enabled=false;}else{if(await Notification.requestPermission()!=='granted')throw Error('Push permission was not granted.');const reg=await navigator.serviceWorker.register('/web/push-worker.js',{scope:'/web/'});await navigator.serviceWorker.ready;const raw=atob(data.vapid_public_key.replace(/-/g,'+').replace(/_/g,'/'));const key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const r=await fetch('/api/v1/account-notifications/push',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(sub.toJSON())});if(!r.ok){await sub.unsubscribe();throw Error('Push registration failed.');}enabled=true;}message=enabled?'Push enabled on this device.':'Push disabled on this device.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
 onMount(load);
</script>
<section class="space-y-4 rounded-2xl border bg-card p-4"><h2 class="text-xl font-semibold">{t($locale,'Notifications')}</h2><p class="text-sm text-muted-foreground">{t($locale,'Choose email, push, both or neither for each category. Account security emails are always sent.')}</p>
 {#if data}<div class="space-y-3">{#each Object.entries(data.categories) as [category,channels]}<div class="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><span class="font-medium">{t($locale,names[category]??category)}</span><div class="flex gap-4"><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={data.categories[category].email}/>{t($locale,'Email')}</label><label class="flex min-h-11 items-center gap-2"><input type="checkbox" bind:checked={data.categories[category].push}/>{t($locale,'Push')}</label></div></div>{/each}</div><div class="flex flex-wrap gap-3"><button disabled={busy} onclick={save} class="min-h-11 rounded-lg bg-primary px-4 text-primary-foreground">{t($locale,'Save notification settings')}</button><button disabled={busy||!supported} onclick={push} class="min-h-11 rounded-lg border px-4">{t($locale,enabled?'Disable push on this device':'Enable push on this device')}</button></div>{/if}
 <p class="text-sm text-muted-foreground">{t($locale,'Push requires HTTPS. On iPhone and iPad, install MediaManager on the Home Screen and enable push from there.')}</p>{#if message}<p role="status" class="text-sm">{t($locale,message)}</p>{/if}
</section>
